try:
    print('>>> f = delattr')
    print('>>> x = range(0)')
    print('>>> y = b""')
    print('>>> f(x, y)')
    f = delattr
    x = range(0)
    y = b""
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
